using System.Collections.ObjectModel;

namespace YDKE_Windows;

internal sealed record HelpSection(string Id, string Title, string Body);

internal sealed record HelpDocument(string Title, string Intro, IReadOnlyList<HelpSection> Sections)
{
    public string ReadableText => string.Join("\n\n", new[] { Intro }.Concat(Sections.Select(section => $"{section.Title}\n{section.Body}")));
}

internal static class HelpContent
{
    private static readonly IReadOnlyDictionary<string, HelpDocument> Documents =
        new ReadOnlyDictionary<string, HelpDocument>(new Dictionary<string, HelpDocument>(StringComparer.Ordinal)
        {
            ["tr"] = Turkish(),
            ["en"] = English(),
            ["de"] = German(),
            ["fr"] = French(),
            ["es"] = Spanish(),
            ["pt"] = Portuguese(),
            ["nl"] = Dutch(),
        });

    public static HelpDocument Get(string language) => Documents.TryGetValue(language, out var document)
        ? document
        : Documents[UserSettings.DefaultUiLanguage];

    private static HelpDocument Turkish() => new(
        "YDKE yardımı",
        "YDKE, kelime öğrenmeyi kartlar, testler, kelime listeleri, istatistikler ve 25 yerel oyunla destekleyen Windows uygulamasıdır. Bu yardım sayfası uygulamanın gerçek masaüstü akışını anlatır. Metni seçip kopyalayabilir, Tab ve Shift+Tab ile kontroller arasında ilerleyebilir, kısa yardım pencerelerini Önceki sayfa ve Sonraki sayfa düğmeleriyle okuyabilirsin.",
        [
            new("start", "Başlarken: üst çubuk ve menü", "Üst çubukta Öğrenme dili ve Seviye seçicileri bulunur. Bunlar hangi kelime havuzuyla çalışacağını belirler. Uygulama dili üst çubukta değil, Ayarlar > Çalışmam bölümündeki Uygulama dili seçicisinden değiştirilir. Pencereli veya Tam ekran düğmesi görünüm modunu değiştirir; F11 aynı işi yapar, Esc tam ekrandan çıkar.\n\nSol menü Ana Sayfa, Kartlar, Test, Kelimeler, Phrasal Verbs, Basit Oyunlar, Karmaşık Oyunlar, İstatistikler, Ayarlar, Yardım ve Hakkında bölümlerini açar. Phrasal Verbs ekranı açıkken Seviye seçicisi geçici olarak devre dışı bırakılır; diğer ekranlara geçince yeniden etkinleşir. Menü kapalıyken her öğe simgesiyle görünür; klavyeyle Tab kullanıldığında erişilebilir adı okunur. Bir bölüm açıldığında uygulama önceki çalışma bağlamını korur."),
            new("accessibility", "Erişilebilirlik ve klavye kullanımı", "Kontrollerin metin etiketleri renk veya simgeye tek başına bağlı değildir. Düğmeler en az 48 piksel hedef alanı, görünür odak çerçevesi ve yüksek karşıtlık desteği kullanır. Metin boyutu Ayarlar > Renkler ve yazılar bölümünde artırılabilir; uygulama küçük ayarlarda bile okunabilir bir yazı tabanını korur.\n\nTab bir sonraki kontrole, Shift+Tab önceki kontrole gider. Enter seçili düğmeyi çalıştırır. Kartlarda Boşluk anlamı gösterir; 1–4 değerlendirmeyi seçer; sol ve sağ oklar kartlar arasında ilerler; U kelimeyi biliniyor olarak işaretler. Testte 1–4 seçenekleri seçer ve Enter yanıt kaydedildikten sonra Devam düğmesini çalıştırır. Oyunlarda düğmelerin adları, durumları ve yardım metinleri ekran okuyuculara aktarılır. Renkli doğru/yanlış göstergeleri her zaman metin veya simgeyle birlikte verilir."),
            new("cards", "Kartlar: gör, düşün ve ilerle", "Kartlar bölümü kısa bir çalışma oturumu başlatır. Önce kelimeyi düşün, sonra Anlamı göster düğmesini seç. Anlam ve örnek cümle görünür; Dinle düğmesi kelimeyi cihazındaki hedef dil sesiyle okur. Favori ve Bu kelimeyi biliyorum düğmeleri kişisel işaretlerdir.\n\nAnlamı okuduktan sonra Sonraki düğmesini seçerek kartı tamamla ve ilerle. Önceki ve Sonraki düğmeleri kayıtlı kartlar arasında hareket eder; Geri al son tamamlanan kartı geri getirir. Kelimeyi biliniyor olarak işaretlemek için Kartlar veya Kelimeler içindeki biliniyor aracını kullanabilirsin.\n\nKart açılmadan Sonraki düğmesi etkinleşmez. Bu, anlamı görmeden ilerlemeyi önler."),
            new("quiz", "Test: kaydedilen yanıt ve geri bildirim", "Test her zaman seçili Öğrenme dili ve Seviye için numaralı test adacıkları ızgarasıyla açılır. Testini açmak için bir adacık seç. Her adacık 20 soru içerir; son adacıkta kalan soru sayısı 20'den az olabilir.\n\nHer adacık kendi sorularını ve seçeneklerini olduğu gibi, yanıtlarını ve kaldığın yeri ayrı kaydeder. Kutucuğunu açınca kayıtlı oturuma kaldığın yerden devam edersin; tamamlanan adacık sonuçlarını açar. Başka bir test adacığı seç, ilerlemeni silmeden seçiciye döner.\n\nHer soruda anlamı oku ve dört kelime arasından birini seç. Seçimin hemen kaydedilmezse uygulama sonraki soruya geçmez. Geri bildirim doğru yanıtı, senin seçimini ve gerekiyorsa açıklamayı metinle gösterir. Örnek veya karşılaştırma için Yanıta bakalım'ı aç. Devam düğmesi yalnızca yanıt kaydedildikten sonra etkinleşir; düğmeyi veya Enter'ı kullanarak sonraki soruya geçebilirsin. Sonuç ekranı ilk deneme doğruluğunu oyun puanlarından ve kart öz değerlendirmelerinden ayrı tutar.\n\nBu testi yeniden çöz, o adacığın testini tüm sorularıyla baştan başlatır."),
            new("words", "Kelimeler: ara, süz ve tek tek çalış", "Kelimeler bölümü aynı anda uzun bir listeyi sıkıştırmak yerine bir kelimeyi tam olarak gösterir. Arama kutusunda kelime, anlam veya kategori arayabilirsin. Kategori, biliniyor ve favori filtrelerini birlikte kullanabilirsin. Filtreleri temizle sonuçları başlangıç durumuna döndürür.\n\nÖnceki kelime ve Sonraki kelime düğmeleri sonuçlar arasında ilerler. Her kelime için anlam, örnek, Dinle, favori ve biliniyor araçları bulunur. Biliniyor işareti Kartlar ile ortaktır; burada işaretlediğin kelime Kartlar içinde de işaretli görünür.\n\n20 soruluk test seç düğmesi, seçili Öğrenme dili ve Seviye için numaralı test adacıkları ızgarasını açar. Arama filtreleri testleri değiştirmez. Her adacık 20 sorudur; sonuncuda daha az olabilir. Her adacık kendi sorularını ve seçeneklerini olduğu gibi, yanıtlarını ve kaldığın yeri ayrı kaydeder. Kutucuğunu açarak kayıtlı oturuma devam et veya tamamlandıysa sonuçlarını gör. Seçiciye dönmek ilerlemeyi silmez. Bu testi yeniden çöz, o adacığın testini tüm sorularıyla baştan başlatır."),
            new("games", "Oyunlar: 25 farklı çalışma biçimi", "Basit Oyunlar ve Karmaşık Oyunlar menüleri toplam 25 yerel oyunu gösterir. Oyun kataloğu tek bir pencerede açılır; oyun kartını seçip Oyna düğmesine bas. Oyun ekranındaki İpucu, Nasıl oynanır ve örnek/ampul düğmeleri sorunun ne istediğini açıklar. Bazı oyunlar süre, bazıları can veya tur kullanır; üstteki HUD puan, seri, tur ve süre/can bilgisini metin olarak gösterir.\n\nOyunlar şunlardır: Hangman, Cloze Test, Dictation, Speed Round, Survival Streak, True or False, Word Class, Memory, Odd One Out, Word Race, Sentence Scramble, Reading Comprehension, Word Morph, Bingo, Boss Rush, CodyCross, Crossword, Daily Challenge, Scrabble, Word Guess, Category Sprint, Listening Choice, Matrix, Clue Detective ve Scramble.\n\nHer oyunun kelime havuzu Öğrenme dili ve Seviye seçicilerine bağlıdır. Bazı oyunlarda hedef dil için yeterli uzunlukta veya örnekli kelime yoksa oyun içeriği sınırlı olabilir; bu bir hesap veya internet hatası değildir. Oyun bırakılırken onay istenir; kaydedilmiş öğrenme ilerlemesi korunur."),
            new("statistics", "İstatistikler: ölçümleri birbirine karıştırma", "İstatistikler üç bölüme ayrılır. Genel bakış bugün ve son yedi gündeki farklı kelimeleri, mevcut çalışma dilini ve tekrar zamanı gelen kelimeleri gösterir. Yanıtlar test ilk denemelerini, puanlanan oyun yanıtlarını ve tamamlanan oyunları ayrı gösterir. Kartlar bölümü kart öz değerlendirmelerini ve eski sayaç ayrıntılarını sunar.\n\nKart öz değerlendirmeleri doğruluk puanı değildir: Yardım et, Zor, Biliyordum ve Kolay senin kendi hatırlama değerlendirmelerindir. Her satırda renk, değerlendirme adı, açıklama ve sayı birlikte bulunur. Büyük metin ayarında satırlar sayfalara ayrılır; Önceki ve Sonraki düğmeleri sayfayı değiştirir ve ekran okuyucu mevcut sayfayı duyurur. Renkler okunamasa bile metin anlamı korur."),
            new("settings", "Ayarlar: çalışma, görünüm ve yetişkin araçları", "Çalışmam bölümünde Uygulama dili, günlük hedef, Daha az hareket ve Süre sınırı olmadan oyna seçenekleri bulunur. Günlük hedef 1 ile 10.000 arasında tam sayı olmalıdır. Değişiklikler Kaydet seçilene kadar taslaktır; geçersiz sayı kaydedilmez ve hata metni doğrudan hedef alanında gösterilir.\n\nRenkler ve yazılar bölümünde metin boyutu yüzde 85–140 arasında ayarlanır. Arka plan, düğme ve panel renklerini seçebilirsin; uygulama önizlemede yazı ve sınır karşıtlığını korur. Gelişmiş renk araçları açılır bir bölümde bulunur ve HEX değerleri doğrudan girilebilir.\n\nBüyükler için bölümünde yerel yedek dışa/içe aktarma ve tüm yerel ayarları/öğrenme hafızasını sıfırlama araçları vardır. Sıfırlama iki kez açıkça belirtilir ve onay ister; yalnızca bu cihazdaki yerel veriler etkilenir."),
            new("cloud", "Yerel yedekler ve gizlilik", "YDKE ile öğrenmek için hesap veya oturum açma gerekmez. Öğrenme içeriği ve ilerleme bu cihazda yerel olarak saklanır.\n\nAyarlar > Büyükler için bölümündeki Bir kopya oluştur, yerel yedek dosyası çıkarır. Bir kopya aç işlemi dosyayı doğrular, önce güvenlik kopyası alır, sonra onayla birlikte yerel ayar ve ilerlemeyi değiştirir.\n\nVarsayılan çalışma tamamen çevrimdışıdır. Yedek dosyalar yalnızca öğrenme verisini taşır; hesap bilgisi veya gizli kimlik verisi içermez."),
            new("audio", "Dinle düğmesi ve sorun giderme", "Dinle düğmesi kelimeyi hedef dilde Windows 11'in yerel konuşma sesleriyle okumayı dener. Dinle çalışmıyorsa şu adımları uygula: Windows Ayarlar > Zaman ve dil > Dil ve bölge > Dil ekle (gerekirse) > ilgili dili seç > Dil seçenekleri > Konuşma paketini yükle. Kurulumdan sonra YDKE'yi kapatıp yeniden aç. Uygulama ses için internetten bir servis çağırmaz.\n\nSes düğmesi etkin değilse oyun veya kelime için sesli içerik bulunmuyor olabilir. Bu durum kelimeyi yazılı olarak çalışmanı engellemez. Daha az hareket seçeneği animasyonları azaltır; ses özelliğini kapatmaz.\n\nBir dil veya seviye değişikliğinden sonra kelime havuzu yeniden yüklenebilir. Kısa bir yükleme göstergesi görünürken düğmeler geçici olarak devre dışı bırakılır; bu sırada seçimleri tekrarlamak gerekmez."),
            new("data", "İçerik, kaynaklar ve uygulama lisansı", "Kelime listeleri ve okuma içerikleri uygulamayla birlikte yerel olarak paketlenir. Bazı tanım ve örnek cümleler açık topluluk kaynaklarından gelir; ilgili atıf ve lisans bilgileri Hakkında sayfasında ve paketteki NOTICE dosyasında bulunur. YDKE'nin kendi kaynak kodu ve arayüzü PolyForm Noncommercial License 1.0.0 kapsamındadır.\n\nTicari kullanım izinsiz değildir. Kişisel kullanım, öğrenme, araştırma, hobi projeleri, okullar, üniversiteler, kamu kurumları ve kâr amacı gütmeyen kuruluşlar için lisans metnindeki koşullar geçerlidir. Tam telif sahipleri, izin adresleri ve lisans bağlantısı Hakkında sayfasının en üstündeki uygulama lisansı bölümündedir.\n\nYDKE, YDS, YÖKDİL, ÜDS, TOEFL, telc veya CEFR kurumlarının resmi ürünü değildir. Sınav ve marka adları yalnızca çalışma hedefini açıklamak için kullanılır."),
        ]);

    private static HelpDocument English() => new(
        "YDKE help",
        "YDKE is a native Windows vocabulary app with cards, quizzes, word lists, statistics and 25 local games. This help describes the actual desktop app, not the retired web interface. You can select and copy the text, move with Tab and Shift+Tab, and read short help pages with Previous page and Next page.",
        [
            new("start", "Getting started: the top bar and menu", "The top bar contains Learning language and Level selectors. They define the vocabulary pool used by Cards, Quiz, Words, Phrasal Verbs and Games. App language is changed in Settings > My practice, not in the top bar. Windowed or Full screen changes the window mode; F11 does the same and Esc leaves full screen.\n\nThe left navigation opens Home, Cards, Quiz, Words, Phrasal Verbs, Simple Games, Complex Games, Statistics, Settings, Help and About. On the Phrasal Verbs page, the Level selector is intentionally disabled; it becomes available again on other pages. Every navigation item has a text name for keyboard and screen-reader users. Changing a section keeps the current study context.")
                , new("accessibility", "Accessibility and keyboard use", "Controls do not depend on colour or an icon alone. Buttons use at least 48-pixel targets, visible focus visuals and high-contrast support. Increase text size in Settings > Colors & text; the app keeps a readable text floor even at smaller settings.\n\nTab moves forward and Shift+Tab moves backward. Enter invokes the focused button. In Cards, Space reveals the meaning, 1–4 select a rating, arrow keys move between cards and U toggles known. In Quiz, 1–4 select an answer and Enter continues after the saved answer. Games expose names, states and help text to assistive technology. Correct and incorrect states always include text or symbols in addition to colour.")
                , new("cards", "Cards: reveal, read and continue", "Start a short Cards session. Think about the word, then choose Show meaning. The meaning and example appear; Listen uses a locally installed voice for the target language. Favourite and I know this word are personal marks.\n\nAfter reading the meaning, choose Next to complete the card and continue. Previous and Next move through saved cards; Undo brings back the last completed card. Use the known tool in Cards or Words when you want to mark a word as known.\n\nNext stays disabled until the meaning is revealed. This keeps the learning step clear and prevents moving on without seeing the answer.")
                , new("quiz", "Quiz: saved answers and feedback", "Quiz always opens the numbered test-island grid for the selected Learning language and Level. Choose an island to open its test. Each island contains 20 questions, except the last island, which may contain fewer.\n\nEach island saves its own exact questions, choices, answers and current position. Opening its tile resumes that saved session; a completed island opens its results. Choose another test island returns to the picker without discarding progress.\n\nRead the meaning and choose one of four words. The app does not move on until the answer has been saved. Feedback names the correct answer, your choice and any useful comparison text. Look at the answer opens an example or comparison. Continue becomes available only after the saved answer. The result records first-attempt quiz accuracy separately from game scores and Cards self-ratings.\n\nTry this test again restarts the whole test for that island from the beginning.")
                , new("words", "Words: search, filter and practise", "Words shows one complete result at a time instead of compressing a long list. Search by word, meaning or category and combine category, known and favourite filters. Clear filters returns to the starting results.\n\nPrevious word and Next word move between matches. Each result includes meaning, example, Listen, favourite and known tools. Known is shared with Cards, so a mark made in either place is visible in the other.\n\nChoose a 20-question test opens the numbered test-island grid for the selected Learning language and Level. Search filters do not change the tests. Each island has 20 questions; the last may have fewer. Each saves its own exact questions, choices, answers and position. Open its tile to resume the saved session or see completed results. Returning to the picker keeps progress. Try this test again restarts that island's whole test.")
                , new("games", "Games: 25 study mechanics", "Simple Games and Complex Games contain 25 local games. Choose a game card and Play. The game toolbar offers How to play, Hint and, where useful, a definition/example bulb. The HUD presents score, streak, round and lives or time as text as well as visual progress.\n\nThe current catalog is Hangman, Cloze Test, Dictation, Speed Round, Survival Streak, True or False, Word Class, Memory, Odd One Out, Word Race, Sentence Scramble, Reading Comprehension, Word Morph, Bingo, Boss Rush, CodyCross, Crossword, Daily Challenge, Scrabble, Word Guess, Category Sprint, Listening Choice, Matrix, Clue Detective and Scramble.\n\nGames use the selected Learning language and Level. Some mechanics need suitable word length, examples or reading content; limited availability is a dataset constraint, not an account or internet error. Leaving a game asks for confirmation and keeps saved learning progress.")
                , new("statistics", "Statistics: keep measurements separate", "Statistics has Overview, Answers and Cards sections. Overview shows unique words today and in the last seven days, the current study language and due reviews. Answers separates first-attempt Quiz results, scored Game answers and completed games. Cards shows self-ratings and retained legacy counters.\n\nCards self-ratings are not accuracy scores. Help me, Hard, I knew it and Easy describe your own recall judgement. Each row includes a label, plain-language description and count; colour is only an additional cue. Large text settings page the rows, and Previous/Next announces the current page to screen readers.")
                , new("settings", "Settings: practice, appearance and grown-up tools", "My practice contains App language, daily goal, Less movement and Play without a timer. The daily goal is a whole number from 1 to 10,000. Changes are drafts until Save; invalid input is rejected with an inline message.\n\nColors & text controls text size from 85% to 140% and lets you preview background, button and panel colours. The preview keeps readable text and boundary contrast. Advanced colour tools are presented separately and accept HEX values.\n\nFor grown-ups contains local backup export/import and a confirmation-gated reset of local settings and learning memory.")
                , new("cloud", "Local backups and privacy", "No account or sign-in is required to learn with YDKE. Learning content and progress are stored locally on this device.\n\nIn Settings > For grown-ups, Make a copy exports a local backup file. Open a copy validates the file, creates a safety copy first, and then replaces local settings and progress after confirmation.\n\nLearning is offline by default. Backup files carry only learning data and do not include account or secret credential information.")
                , new("audio", "Listen and troubleshooting", "Listen uses an installed Windows 11 speech voice for the target language. If Listen does not work, follow these steps: Windows Settings > Time & language > Language & region > Add a language (if needed) > select the language > Language options > install Speech. Restart YDKE after installation. YDKE does not call an online speech service for learning.\n\nA disabled Listen control may mean that the current word or game has no audio target. Text practice remains available. Less movement reduces animations but does not turn audio off.\n\nChanging a language or level may reload the vocabulary pool. During the short loading state, controls are disabled so the same change is not submitted twice.")
                , new("data", "Content, sources and licence", "Vocabulary and reading content is bundled locally. Some definitions and examples come from open community sources; attribution and licence details are in the About page and the NOTICE file shipped with the app. YDKE's own source code and interface are covered by the PolyForm Noncommercial License 1.0.0.\n\nCommercial use requires prior permission. The licence terms cover personal study, research, hobby projects, schools, universities, public institutions and nonprofit organisations as described in the licence. Copyright holders, permission addresses and the full licence link appear at the top of About.\n\nYDKE is not an official product of YDS, YÖKDİL, ÜDS, TOEFL, telc or CEFR organisations. Exam and brand names describe study goals only.")
        ]);

