    private static HelpDocument Localized(string language, string title, string intro, params string[] headings)
    {
        var bodies = language switch
        {
            "de" => GermanBodies(),
            "fr" => FrenchBodies(),
            "es" => SpanishBodies(),
            "pt" => PortugueseBodies(),
            "nl" => DutchBodies(),
            _ => EnglishBodies(),
        };
        var ids = new[] { "start", "accessibility", "cards", "quiz", "words", "games", "statistics", "settings", "cloud", "audio", "data" };
        return new HelpDocument(title, intro, headings.Select((heading, index) => new HelpSection(ids[index], heading, bodies[index])).ToArray());
    }

